const item = $input.first();
const b = item.binary.data;
b.fileName = 'titelei.zip';
b.fileExtension = 'zip';
b.mimeType = 'application/zip';
return [item];

const eingabe = $input.first();
const f = $('Formular').first().json;

// Kontaktadresse = Initialen des Pseudonyms, klein, @example.com
function mailAus(autor) {
  const teile = String(autor == null ? '' : autor).split(/\s+/).filter(Boolean);
  const initialen = teile
    .map(function (t) { return t.replace(/[^A-Za-zÄÖÜäöüß]/g, '').charAt(0); })
    .filter(Boolean).join('').toLowerCase();
  return initialen ? initialen + '@example.com' : '';
}

const mail = mailAus(f['Autor']);

const map = {
  BUCH_TITEL: f['Titel'],
  BUCH_UNTERTITEL: f['Untertitel'],
  BUCH_AUTOR: f['Autor'],
  BUCH_KONTAKT: mail
};

function xmlEscape(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function ersetzeInAbsaetzen(xml, map, mail) {
  let treffer = 0;
  const neuXml = xml.replace(/<w:p(?:\s[^>]*)?>[\s\S]*?<\/w:p>/g, (absatz) => {
    const teile = [];
    const re = /(<w:t(?:\s[^>]*)?>)([\s\S]*?)(<\/w:t>)/g;
    let m;
    while ((m = re.exec(absatz)) !== null) {
      teile.push({ start: m.index, ende: re.lastIndex, oeffner: m[1], text: m[2], schliesser: m[3] });
    }
    if (!teile.length) return absatz;
    const gesamt = teile.map(t => t.text).join('');
    if (gesamt.indexOf('{{') === -1 && gesamt.toUpperCase().indexOf('XXX@') === -1) return absatz;

    let neu = gesamt;
    neu = neu.split('{{BUCH_AUTOR}}]').join(xmlEscape(map.BUCH_AUTOR));
    for (const k of Object.keys(map)) {
      neu = neu.split('{{' + k + '}}').join(xmlEscape(map[k]));
    }
    if (mail) neu = neu.replace(/XXX@example\.com/gi, mail);
    if (neu === gesamt) return absatz;
    treffer++;

    const ausgabe = [];
    let pos = 0;
    teile.forEach((t, i) => {
      ausgabe.push(absatz.slice(pos, t.start));
      let oeffner = t.oeffner;
      let inhalt = '';
      if (i === 0) {
        inhalt = neu;
        if (!/xml:space=/.test(oeffner)) oeffner = oeffner.replace(/^<w:t/, '<w:t xml:space="preserve"');
      }
      ausgabe.push(oeffner + inhalt + t.schliesser);
      pos = t.ende;
    });
    ausgabe.push(absatz.slice(pos));
    return ausgabe.join('');
  });
  return { xml: neuXml, treffer };
}

function crc32(buf) {
  if (!crc32.tabelle) {
    const t = [];
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c >>> 0;
    }
    crc32.tabelle = t;
  }
  const t = crc32.tabelle;
  let crc = -1;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ t[(crc ^ buf[i]) & 0xFF];
  return (crc ^ -1) >>> 0;
}

function zipSchreiben(eintraege) {
  const lokale = [], zentrale = [];
  let offset = 0;
  const zeit = 0, datum = (26 << 9) | (1 << 5) | 1;
  for (const e of eintraege) {
    const name = Buffer.from(e.pfad, 'utf8');
    const daten = e.buf;
    const crc = crc32(daten);
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0, 6);
    lh.writeUInt16LE(0, 8); lh.writeUInt16LE(zeit, 10); lh.writeUInt16LE(datum, 12);
    lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(daten.length, 18); lh.writeUInt32LE(daten.length, 22);
    lh.writeUInt16LE(name.length, 26); lh.writeUInt16LE(0, 28);
    lokale.push(lh, name, daten);
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6);
    ch.writeUInt16LE(0, 8); ch.writeUInt16LE(0, 10); ch.writeUInt16LE(zeit, 12); ch.writeUInt16LE(datum, 14);
    ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(daten.length, 20); ch.writeUInt32LE(daten.length, 24);
    ch.writeUInt16LE(name.length, 28); ch.writeUInt16LE(0, 30); ch.writeUInt16LE(0, 32);
    ch.writeUInt16LE(0, 34); ch.writeUInt16LE(0, 36); ch.writeUInt32LE(0, 38); ch.writeUInt32LE(offset, 42);
    zentrale.push(ch, name);
    offset += 30 + name.length + daten.length;
  }
  const zBuf = Buffer.concat(zentrale);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(eintraege.length, 8); eocd.writeUInt16LE(eintraege.length, 10);
  eocd.writeUInt32LE(zBuf.length, 12); eocd.writeUInt32LE(offset, 16); eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...lokale, zBuf, eocd]);
}

const eintraege = [];
let treffer = 0;
let gefunden = false;

for (const key of Object.keys(eingabe.binary || {})) {
  const b = eingabe.binary[key];
  const pfad = (b.directory ? b.directory + '/' : '') + b.fileName;
  let buf = await this.helpers.getBinaryDataBuffer(0, key);
  if (pfad === 'word/document.xml') {
    gefunden = true;
    const r = ersetzeInAbsaetzen(buf.toString('utf8'), map, mail);
    treffer = r.treffer;
    buf = Buffer.from(r.xml, 'utf8');
  }
  eintraege.push({ pfad, buf });
}

if (!gefunden) throw new Error('word/document.xml nicht im Archiv gefunden');
if (treffer === 0) throw new Error('Nichts zu ersetzen - Datei war vermutlich schon bearbeitet');

const zip = zipSchreiben(eintraege);
const bin = await this.helpers.prepareBinaryData(zip, f['Dateiname'], 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');

return [{ json: { ersetzte_absaetze: treffer, kontakt: mail, dateien: eintraege.length, bytes: zip.length }, binary: { data: bin } }];
